-- Closes a real catalog gap found live 2026-08-25: zero products existed under
-- category 'skin'/'skincare'/'hair'/'haircare', so the "Skin and hair
-- (hormone-related)" concern in the ecosystem quiz could never produce a local
-- match no matter how the concern-to-category mapping was fixed (see the
-- recommendationEngine.js fix in the same session). All three products below
-- were verified live on the brand's own site (2026-08-25): real current price,
-- real product image URL, real product page URL. ON CONFLICT DO NOTHING —
-- never touches an existing row even if this is run twice.

insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-nutrafol-postpartum', 'Nutrafol Postpartum', 'Nutrafol', 'hair', 'physical', 'An OBGYN-developed daily hair growth supplement for the first year after childbirth and while breastfeeding, formulated around the hormonal shift — estrogen and progesterone dropping while cortisol rises — that drives postpartum shedding.', '$88/month ($70.40/month on subscription)', 'https://images.ctfassets.net/0rbfqd9c4jdo/29t1FkqJzForpVAyo07BNw/18fbcdd867e039e27d6dfa638e448e17/pdp-postpartum-package-spu.jpg?fl=progressive', 'https://nutrafol.com/hair/women/product/core/postpartum/', '["hair","postpartum","hormone-free","breastfeeding-friendly"]'::jsonb, '["hair-growth","postpartum-recovery"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not evaluated by the FDA. These statements have not been evaluated by the FDA and this product is not intended to diagnose, treat, cure, or prevent any disease.","materials":"Shatavari, DHA Omega-3s, Apple Polyphenols, Tocotrienol Complex, Stinging Nettle, Collagen-OSA, and Theanine — 100% drug-free, gluten/dairy/soy/gelatin-free, non-GMO.","recalls":"No recalls found.","sideEffects":"Formulated to be breastfeeding-friendly with ingredients used within FDA-set doses for postpartum women; not studied in pregnancy, so the brand recommends switching to it only after birth. Consult your doctor before starting any new supplement, especially if on blood-thinning medication."}'::jsonb, 'Targets the three drivers of postpartum shedding — physical/emotional stress, the estrogen/progesterone/cortisol shift after birth, and nutrient depletion from pregnancy and breastfeeding — with a formula the brand states was developed with an OBGYN and contains no ingredients found to be contraindicated in breastfeeding. As with any supplement route for hair loss, it works over months (the brand states 3-6+), not immediately, and doesn''t address hair loss caused by something else (thyroid disease, iron deficiency, telogen effluvium unrelated to childbirth) — worth ruling out with a clinician if shedding is unusually severe or doesn''t improve.', null, 'Nutrafol states two brand-sponsored studies of 60+ postpartum women found improvement in shedding and hairline fullness starting around 2-4 months and continuing through 6-8 months of daily use — these are the brand''s own studies, not independent, peer-reviewed, placebo-controlled trials, and no independent study of this specific product was found. Postpartum hair shedding is a well-documented, usually self-resolving physiological event (typically peaking 2-3 months postpartum and normalizing within 6-15 months on its own); this product is a support during that window, not something with independent evidence that it changes the underlying timeline.', 'brand', 'Sourced from Nutrafol''s own site and its brand-sponsored clinical study summaries; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-nutrafol-balance', 'Nutrafol Women''s Balance', 'Nutrafol', 'hair', 'physical', 'A hair growth supplement for women 45+ formulated for perimenopause and menopause-related hair thinning, with published clinical studies specifically in menopausal women — the brand states it''s the only hair growth supplement with that.', '$88/month ($70.40/month on subscription)', 'https://images.ctfassets.net/0rbfqd9c4jdo/RwXGiCToo66NwQtJfRxgW/6ab7faac1286129d6d775d6b33fc48a6/BAL1_6.png', 'https://nutrafol.com/hair/women/product/core/balance/', '["hair","menopause","perimenopause"]'::jsonb, '["hair-growth","menopause-support"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Dietary supplement; not evaluated by the FDA. These statements have not been evaluated by the FDA and this product is not intended to diagnose, treat, cure, or prevent any disease.","materials":"See brand site for the full Synergen Complex ingredient list; formulated for hormonal-change-related thinning specifically (as distinct from the standard 18-44 Nutrafol Women formula).","recalls":"No recalls found.","sideEffects":"Consult a clinician before use if you have a medical condition or take medications, especially anticoagulant/blood-thinning drugs."}'::jsonb, 'Positioned specifically for the hormonal drivers of hair thinning in perimenopause/menopause (declining estrogen affecting the hair growth cycle), distinct from Nutrafol''s general-purpose formula for younger women. Same caveat as any supplement-based approach: it works gradually over months, and thinning with other red flags (patchy bald spots, scalp inflammation, rapid onset) warrants a dermatologist visit to rule out a separate cause before assuming it''s purely hormonal.', null, 'The brand states this formula has published clinical studies specifically in menopausal women with hair thinning, which it markets as differentiating it from competitors — those studies are brand-sponsored, not independent third-party trials, and no independent study of this specific product was found. General hormone-related hair thinning in menopause is a well-established clinical phenomenon; that broader evidence base doesn''t itself validate this specific formula''s effectiveness.', 'brand', 'Sourced from Nutrafol''s own site and its brand-sponsored clinical study claims; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb),
  ('p-womaness-fountain-glow', 'Womaness Fountain of Glow', 'Womaness', 'skincare', 'physical', 'A vitamin C and antioxidant face serum from Womaness, a menopause-focused brand, formulated to brighten dull or uneven skin tone as complexion changes with hormonal shifts in perimenopause and menopause.', '$29.99', 'https://womaness.com/cdn/shop/files/FountainofGlow_MainImage_1200x.jpg?v=1756159607', 'https://womaness.com/products/fountain-of-glow', '["skin","menopause","perimenopause"]'::jsonb, '["skin-support","menopause-support"]'::jsonb, '[]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic product; not an FDA-evaluated drug.","materials":"Vitamin C and antioxidant serum blend — see brand site for full ingredient list.","recalls":"No recalls found.","sideEffects":"Patch test recommended for sensitive skin, as with any new vitamin C serum; consult a dermatologist if you have a diagnosed skin condition."}'::jsonb, 'Declining estrogen in perimenopause and menopause is a well-documented driver of reduced skin collagen, elasticity, and moisture, which can present as dullness or uneven tone — the physiological premise behind targeting this life stage specifically is reasonable. Vitamin C serums broadly have real evidence for brightening and antioxidant support at the ingredient-class level; no independent study of this specific formula''s concentration or efficacy was found, so treat this as a category-appropriate product from a brand focused on this life stage, not a clinically-proven proprietary formula.', null, 'No independent clinical study of this specific product was found. At the ingredient-class level, topical vitamin C has real published evidence for antioxidant protection and mild brightening with consistent use; this product''s specific formulation and concentration haven''t been independently tested.', 'brand', 'Sourced from Womaness''s own site; not independently verified here.', 'curated', false, false, null, true, '{"integrations":[],"badges":[],"isEmergingBrand":false}'::jsonb)
on conflict (id) do nothing;
